        amounts[1] = 10 ether;

        vm.deal(user1, 11 ether); 
        vm.prank(user1);
        yolo.depositETHIntoMultipleRounds{value: 11 ether}(amounts);

        amounts[0] = 0 ether;
        amounts[1] = 2 ether / 100; 

        for (uint256 i = 0; i < 99; i++) {
